package cn.academy.port.client;public final class AcademyClient {public static long epoch=71,session=1,input=3;public static int accepted,ended,lost;public static State state=new State();public static long inputSessionEpoch(){return session;}public static boolean sameInputSessionEpoch(long value){return value==session;}public static boolean singleOwnerEpochMatches(long value){return value==epoch;}public static boolean zeroGapArmorInputMatches(long value,long e){return value==input&&e==epoch;}public static void zeroGapArmorAcceptedInput(long value,long e){if(!zeroGapArmorInputMatches(value,e))throw new AssertionError("unexpected accepted input");accepted++;}public static void zeroGapArmorEndedInput(long value,long e){if(!zeroGapArmorInputMatches(value,e))throw new AssertionError("unexpected ended input");ended++;}public static void zeroGapArmorLocalVisualLost(long value,long e){if(!zeroGapArmorInputMatches(value,e))throw new AssertionError("unexpected lost input");lost++;}public static void reset(){epoch=71;session=1;input=3;accepted=ended=lost=0;state=new State();}public static class State {public int level=5;public String category="meltdowner";public boolean activated=true,overloadFine=true,interfering;public final Presets presets=new Presets();public boolean learned(String skill){return switch(skill){case "zero_gap_armor","scatter_plates","dissipation_curtain","dual_point"->true;default->throw new AssertionError("unexpected learned query "+skill);};}}public static class Presets {public boolean currentContains(String skill){if(!skill.equals("zero_gap_armor"))throw new AssertionError("unexpected preset query");return true;}}}
